class Solution {
public:
    string rankTeams(vector<string>& votes) {
        int n = votes[0].size();  // number of teams / positions
        int m = votes.size();     // number of voters

        // cnt[c-'A'][j] = number of votes where team c is ranked at position j
        vector<vector<int>> cnt(26, vector<int>(n, 0));
        for (const auto& v : votes) {
            for (int j = 0; j < n; j++) {
                cnt[v[j] - 'A'][j]++;
            }
        }

        // Working array of team letters
        vector<char> teams(votes[0].begin(), votes[0].end());

        // Pass 0 (least significant): stable counting sort by team letter, ascending
        {
            vector<int> count(26, 0);
            for (char c : teams) count[c - 'A']++;
            vector<int> start(26, 0);
            for (int i = 1; i < 26; i++) start[i] = start[i - 1] + count[i - 1];
            vector<char> tmp(teams.size());
            for (char c : teams) tmp[start[c - 'A']++] = c;
            teams = tmp;
        }

        // Passes 1..n: stable counting sort by vote count at each position,
        // from position n-1 (least significant) to position 0 (most significant),
        // descending by count.
        for (int pos = n - 1; pos >= 0; pos--) {
            vector<int> count(m + 1, 0);
            for (char c : teams) count[cnt[c - 'A'][pos]]++;
            // start[k] = index where elements with key k should be placed
            // (descending: higher keys get lower indices)
            vector<int> start(m + 1, 0);
            for (int k = m - 1; k >= 0; k--) {
                start[k] = start[k + 1] + count[k + 1];
            }
            vector<char> tmp(teams.size());
            for (char c : teams) {
                int k = cnt[c - 'A'][pos];
                tmp[start[k]++] = c;
            }
            teams = tmp;
        }

        return string(teams.begin(), teams.end());
    }
};
